<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{AcademicRepository,EmployeeRepository,PakistanErpRepository,SettingsRepository};use App\Support\Flash;
final class TeacherAssignmentsController extends AdminPageController{private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():PakistanErpRepository{return new PakistanErpRepository($this->app->database());}public function index(Request$q):Response{return$this->view('teachers/assignments',['pageTitle'=>'Teacher Assignments','activeMenu'=>'classes','activeSubmenu'=>'teacher-assignments','institute'=>(new SettingsRepository($this->app->database()))->institute(),'assignments'=>$this->r()->assignments($this->i()),'teachers'=>(new EmployeeRepository($this->app->database()))->all($this->i(),'',true),'classes'=>(new AcademicRepository($this->app->database()))->withSubjects($this->i())]);}public function store(Request$q):Response{try{$this->r()->saveAssignment($this->i(),(int)$q->input('employee_id'),(int)$q->input('class_id'),(int)$q->input('subject_id')?:null,(int)$q->input('section_id')?:null,(string)$q->input('assignment_type'),(int)user()['id']);Flash::add('success','Teacher assignment saved.');}catch(\Throwable$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/teacher-assignments'));}public function delete(Request$q):Response{$this->r()->deleteAssignment((int)$q->route('id'),$this->i());return Response::redirect(url('/admin/teacher-assignments'));}}
